-- Preserve flagship prompts 1–50. Add 50 discovery lenses for each of 19 sectors.
-- Sector-specific focus areas keep each lens grounded in its operating context.
with sectors(n, category, resources, systems, markets, technology, futures) as (values
 (1, 'Agriculture & Food Systems', 'crop residues, seed diversity, soil biology, rejected harvests and post-harvest losses', 'seasonality, farmer incentives, aggregation, irrigation and cold-chain gaps', 'food ingredients, animal feed, buyer specifications, nutrition and farm incomes', 'drying, fermentation, precision irrigation, storage and food-safe processing', 'water stress, soil depletion, dietary shifts and smallholder resilience'),
 (2, 'Blue Economy & Aquaculture', 'seaweed, fish byproducts, shell waste, coastal biomass and unused port assets', 'hatcheries, feed supply, landing sites, traceability and coastal livelihoods', 'marine ingredients, aquafeed, cold-chain services and verified seafood demand', 'recirculating aquaculture, preservation, marine sensors and low-impact cultivation', 'warming waters, habitat loss, coastal adaptation and changing fish distributions'),
 (3, 'Circular Materials & Waste', 'mixed plastics, discarded textiles, demolition debris, organics and electronic waste', 'collection incentives, sorting purity, reverse logistics and contamination', 'recycled feedstock specifications, repair demand, reuse systems and offtake contracts', 'separation, washing, remanufacturing, depolymerization and material identification', 'product redesign, waste prevention, material scarcity and producer responsibility'),
 (4, 'Energy & Storage', 'waste heat, renewable resources, idle batteries and unused connection capacity', 'demand peaks, grid constraints, equipment maintenance and energy access', 'reliable power, process heat, flexibility services and customer payment capacity', 'storage chemistries, heat pumps, microgrids, efficiency retrofits and load control', 'fuel volatility, electrification, grid resilience and end-of-life equipment'),
 (5, 'Water & Sanitation', 'wastewater nutrients, recoverable water, sludge and underused treatment capacity', 'leakage, collection coverage, household behavior and treatment reliability', 'industrial reuse, safe sanitation, utility procurement and affordable service', 'membranes, leak detection, nutrient recovery and decentralized treatment', 'drought, flooding, watershed degradation and equitable access to clean water'),
 (6, 'Manufacturing & Industrial Systems', 'scrap, offcuts, idle machine hours, tooling and production knowledge', 'changeovers, quality losses, supplier concentration and factory bottlenecks', 'contract manufacturing, spare parts, product tolerances and industrial buyers', 'automation, additive manufacturing, process control and predictive maintenance', 'reshoring, skills shortages, resource productivity and flexible production'),
 (7, 'Construction & Built Environment', 'vacant buildings, demolition materials, excavated soil and underused land', 'permitting delays, contractor incentives, material logistics and building upkeep', 'affordable housing, retrofit buyers, lifecycle cost and procurement constraints', 'modular construction, passive cooling, material testing and building sensors', 'urban heat, population shifts, flood exposure and resilient infrastructure'),
 (8, 'Mobility & Logistics', 'empty return journeys, idle vehicles, warehouse space and shipment data', 'route density, fragmented carriers, border delays and last-mile reliability', 'freight buyers, commuter needs, delivery service levels and willingness to pay', 'routing tools, fleet maintenance, charging infrastructure and cold transport', 'trade corridor shifts, fuel transitions, congestion and transport accessibility'),
 (9, 'Health Systems & Care', 'underused diagnostic capacity, reusable infrastructure and care-worker knowledge', 'referral delays, stockouts, care continuity and clinical workflow burdens', 'patient access, provider procurement, payer incentives and preventive services', 'validated diagnostics, supply-chain monitoring, assistive devices and care coordination', 'aging populations, workforce gaps, outbreak preparedness and equitable care'),
 (10, 'Biotechnology & Bioeconomy', 'fermentation side streams, biomass fractions, microbial diversity and lab capabilities', 'feedstock variability, contamination control, scale-up constraints and biosafety', 'industrial enzymes, biomaterials, bioprocess services and ingredient qualification', 'biocatalysis, downstream purification, strain screening and process monitoring', 'biomanufacturing capacity, sustainable feedstocks, biosecurity and ecological limits'),
 (11, 'Digital Systems & AI', 'unused operational data, legacy workflows, computing capacity and domain expertise', 'data quality, integration friction, human review and organizational incentives', 'workflow pain points, adoption costs, privacy expectations and measurable customer value', 'model evaluation, retrieval, automation, accessibility and secure system integration', 'model commoditization, digital exclusion, interoperability and changing skill needs'),
 (12, 'Education & Skills', 'unused classrooms, practitioner expertise, local-language content and learner projects', 'dropout drivers, credential barriers, teacher workload and employer coordination', 'learner goals, employer demand, training procurement and affordable delivery', 'practice simulations, accessible learning tools, assessment and skills verification', 'changing occupations, lifelong learning, youth employment and digital access'),
 (13, 'Finance & Inclusive Commerce', 'unserved transaction needs, merchant records, savings groups and idle business inventory', 'settlement delays, trust gaps, cash-flow cycles and financial exclusion', 'merchant services, cooperative finance, transparent pricing and customer protection', 'secure payments, consent-based records, reconciliation and fraud detection', 'income volatility, payment interoperability, consumer trust and regulatory change'),
 (14, 'Tourism & Creative Industries', 'local stories, craft knowledge, cultural venues, off-season capacity and creative archives', 'distribution gatekeepers, booking friction, creator incentives and visitor flows', 'niche experiences, licensing, local audiences and fair creator compensation', 'digital production, accessible booking, preservation tools and experience design', 'climate exposure, cultural continuity, travel patterns and platform dependence'),
 (15, 'Minerals & Advanced Materials', 'mine tailings, processing residues, industrial minerals and material substitutes', 'ore variability, beneficiation constraints, transport costs and responsible sourcing', 'purity specifications, specialty materials, traceability and buyer qualification', 'separation, refining, material characterization and low-impact processing', 'critical-material demand, recycling supply, water constraints and community consent'),
 (16, 'Climate & Ecosystem Restoration', 'degraded land, native biodiversity, organic residues and ecosystem knowledge', 'land tenure, restoration incentives, monitoring gaps and community stewardship', 'adaptation services, restoration procurement and credible ecological outcomes', 'remote sensing, field monitoring, soil restoration and nature-based engineering', 'climate uncertainty, biodiversity loss, permanence and ecosystem thresholds'),
 (17, 'Cities & Public Services', 'idle public assets, public-space capacity, service data and community expertise', 'service fragmentation, maintenance backlogs, procurement and access inequities', 'resident needs, municipal budgets, public value and transparent service contracts', 'accessible digital services, asset monitoring and low-cost infrastructure upgrades', 'urban growth, fiscal pressure, demographic change and disaster preparedness'),
 (18, 'Trade & Regional Development', 'local resources, diaspora networks, supplier capabilities and underused corridors', 'customs friction, standards compliance, payment delays and cluster coordination', 'import substitution, regional buyers, export niches and trade finance needs', 'quality testing, traceability, logistics platforms and production upgrading', 'trade realignment, currency volatility, industrial diversification and regional resilience'),
 (19, 'Enterprise & Innovation Strategy', 'existing assets, customer relationships, staff knowledge and dormant intellectual property', 'organizational silos, misaligned incentives, slow decisions and execution constraints', 'adjacent customers, unmet jobs, recurring revenue and defensible differentiation', 'capability transfer, experimentation platforms and process redesign', 'competitive shifts, business-model erosion, succession and long-term adaptability')
), lenses(n, focus, instruction, deliverable, agents) as (values
 (1, 'resources', 'Reveal the hidden inventory of value', 'Separate what is discarded, idle, unmeasured or undervalued. Build a value map connecting each asset to a useful property, transformation, possible buyer and first validation step.', array['resource_agent','opportunity_agent']),
 (2, 'resources', 'Construct a complete value cascade', 'Trace primary outputs, secondary fractions and residual streams. Identify where value is lost at each handoff and propose three complementary businesses that could capture it without double-counting inputs.', array['resource_agent','systems_agent']),
 (3, 'resources', 'Find unconventional uses through functional properties', 'Look beyond current product labels to physical, chemical, informational or service functions. Match those functions to needs in unrelated industries and identify the specification tests each match requires.', array['resource_agent','science_agent','technology_agent']),
 (4, 'resources', 'Expose the economics hidden inside waste', 'Distinguish avoided disposal cost from saleable output value. Compare collection, cleaning, conversion and delivery costs, and show which minimum purity or volume thresholds would make recovery plausible.', array['resource_agent','financial_agent']),
 (5, 'resources', 'Discover the value of idle capacity', 'Map when assets sit unused and who needs the same capability at those times. Design shared-use or service models and test scheduling conflicts, wear, ownership and demand before assuming spare capacity is free.', array['resource_agent','market_agent']),
 (6, 'resources', 'Uncover locally available substitutes for expensive inputs', 'Match required functions to overlooked local resources. Compare consistency, availability, processing needs and switching costs, and design a small equivalence test before claiming substitution is viable.', array['resource_agent','technology_agent']),
 (7, 'resources', 'Identify what becomes valuable only when streams are combined', 'Find complementary resources whose combined use solves a specification or cost problem. Explain the mechanism, incompatibilities, supply ratios and a trial that could disprove the proposed synergy.', array['resource_agent','science_agent','systems_agent']),
 (8, 'resources', 'Reveal value that can be unlocked through separation', 'Decompose mixed streams into distinct fractions, grades or customer uses. Compare the value gained with separation losses and cost, then locate the simplest commercially useful level of separation.', array['resource_agent','technology_agent','financial_agent']),
 (9, 'resources', 'Map ownership and access barriers around overlooked resources', 'Distinguish physical availability from dependable access. Identify rights holders, competing uses, seasonal limits and community interests, then propose fair sourcing arrangements and checks on resource security.', array['resource_agent','risk_agent','strategy_agent']),
 (10, 'resources', 'Compare raw sale with progressively higher-value transformation', 'Build a ladder from basic sale to services, intermediate inputs and specialized products. Show capability requirements, realistic buyers and margin drivers at each rung, including reasons to stop upgrading.', array['resource_agent','financial_agent','strategy_agent']),
 (11, 'systems', 'Expose the bottleneck that controls the whole system', 'Map flows from input to delivered outcome. Identify the constraint that limits throughput, distinguish symptoms from causes, and show which upstream or downstream businesses become viable if it is relieved.', array['systems_agent','causal_agent','opportunity_agent']),
 (12, 'systems', 'Reveal the incentives sustaining an expensive problem', 'Map who benefits from the status quo, who pays for failure and who can authorize change. Design interventions that realign incentives and identify resistance that a technically sound solution might overlook.', array['systems_agent','causal_agent']),
 (13, 'systems', 'Turn a recurring operational failure into an opportunity map', 'Trace failures back to root causes and classify prevention, detection, response and recovery businesses. Rank them by measurable customer loss avoided and the evidence needed to prove improvement.', array['causal_agent','opportunity_agent','market_agent']),
 (14, 'systems', 'Uncover coordination opportunities between fragmented actors', 'Locate handoffs where information, timing or trust breaks down. Compare an intermediary, shared service and cooperative model, including who pays, who governs and why actors would participate.', array['systems_agent','market_agent','strategy_agent']),
 (15, 'systems', 'Find opportunities hidden in time delays', 'Measure waiting, spoilage, queueing and slow decisions across the value chain. Distinguish delay that protects quality from avoidable delay, and design a business around a verifiable reduction in time-to-value.', array['systems_agent','causal_agent','financial_agent']),
 (16, 'systems', 'Map second- and third-order effects of a proposed improvement', 'Trace how solving one constraint changes demand, prices, behavior and resource use elsewhere. Surface adjacent opportunities, displaced livelihoods and rebound effects, with leading indicators for each.', array['systems_agent','causal_agent','foresight_agent']),
 (17, 'systems', 'Discover the missing links of a viable local cluster', 'Map suppliers, processors, service firms and buyers that could use one another’s outputs. Identify the anchor activity and missing shared infrastructure, then sequence development to avoid stranded investments.', array['systems_agent','opportunity_agent','strategy_agent']),
 (18, 'systems', 'Reveal why previous solutions failed to spread', 'Separate technical failure from adoption, incentives, affordability and maintenance failures. Propose alternative designs that address the actual barrier and specify what evidence would favor each explanation.', array['causal_agent','risk_agent','execution_agent']),
 (19, 'systems', 'Identify opportunities in maintenance and reliability', 'Examine recurring breakdowns, spare-part gaps and unplanned downtime. Compare preventive service, repair, refurbishment and outcome-based contracts using lifecycle costs and the capability needed to deliver reliably.', array['systems_agent','technology_agent','financial_agent']),
 (20, 'systems', 'Uncover the smallest intervention with the largest system effect', 'Compare leverage points rather than isolated projects. Explain the causal pathway from each intervention to outcomes, identify unintended consequences, and propose a reversible experiment to test the strongest candidate.', array['systems_agent','causal_agent','execution_agent']),
 (21, 'markets', 'Reveal underserved customers hidden by market averages', 'Segment buyers by their actual job, constraints and purchasing process. Identify groups whose needs are poorly served, the alternatives they use today and an interview plan that could validate willingness to pay.', array['market_agent','opportunity_agent']),
 (22, 'markets', 'Find opportunities created by non-consumption', 'Identify people or organizations unable to use existing solutions because of cost, access, skill or trust. Design a simpler entry offer and show what must remain effective even after features are removed.', array['market_agent','opportunity_agent','strategy_agent']),
 (23, 'markets', 'Expose the gap between a product and the outcome buyers want', 'Map the full customer journey, including setup, operation, maintenance and disposal. Find outcomes buyers still struggle to achieve and compare product, service and guaranteed-performance business models.', array['market_agent','systems_agent']),
 (24, 'markets', 'Discover overlooked business-to-business niches', 'Trace the specialized inputs and services required by larger operators. Identify procurement pain, qualification barriers and a narrow initial offer that a new entrant could credibly supply.', array['market_agent','opportunity_agent','execution_agent']),
 (25, 'markets', 'Reveal where customer specifications create a premium', 'Compare grades, consistency, traceability, delivery and support requirements. Distinguish real buyer value from assumed premium pricing, and design a sample or paid trial to test the proposed differentiation.', array['market_agent','technology_agent','financial_agent']),
 (26, 'markets', 'Find import-replacement opportunities without assuming local production is cheaper', 'Map imported functions to local capabilities and resources. Compare landed cost, reliability, scale and qualification requirements, then identify niches where local responsiveness could offset a cost disadvantage.', array['market_agent','resource_agent','financial_agent']),
 (27, 'markets', 'Uncover the hidden cost of switching to a better solution', 'Map retraining, integration, downtime, trust and contract barriers. Design an adoption pathway that reduces switching risk and identify which customer segment can switch first with the least disruption.', array['market_agent','risk_agent','strategy_agent']),
 (28, 'markets', 'Reveal demand that can be pooled into a viable market', 'Identify buyers whose individual needs are too small or irregular to serve. Test aggregation, subscription or shared procurement models against coordination cost, delivery density and commitment risk.', array['market_agent','systems_agent','financial_agent']),
 (29, 'markets', 'Discover distribution advantages competitors may overlook', 'Map where customers already gather, buy, learn or receive support. Compare partnerships, local operators and direct channels, showing channel incentives, margins and the risk of losing the customer relationship.', array['market_agent','strategy_agent']),
 (30, 'markets', 'Expose the difference between enthusiasm and purchase intent', 'Turn attractive opportunity claims into falsifiable demand hypotheses. Design interviews, samples and paid pilots with explicit success thresholds, and state what negative results would require abandoning the offer.', array['market_agent','risk_agent','execution_agent']),
 (31, 'technology', 'Transfer a useful mechanism from an unrelated industry', 'Find analogous problems solved elsewhere and explain the mechanism behind the solution. Compare operating conditions, integration needs and failure modes, then propose a low-cost test of transferability.', array['science_agent','technology_agent','opportunity_agent']),
 (32, 'technology', 'Reveal low-technology alternatives to a complex solution', 'Separate essential functions from fashionable features. Compare manual, mechanical, biological and digital approaches where relevant, using reliability, repairability, training and total cost rather than novelty alone.', array['technology_agent','financial_agent','risk_agent']),
 (33, 'technology', 'Find research-to-market gaps hiding a commercial opportunity', 'Identify scientific mechanisms that could solve an unmet operational need. Separate demonstrated findings from extrapolation, list missing experiments and outline a credible path from laboratory result to customer trial.', array['science_agent','evidence_agent','technology_agent']),
 (34, 'technology', 'Expose scale-up risks before committing to a large facility', 'Compare bench, pilot and commercial conditions. Identify changes in mass transfer, quality control, staffing, supply or integration that could break the economics, then define staged scale-up gates.', array['technology_agent','risk_agent','execution_agent']),
 (35, 'technology', 'Discover opportunities in measuring what is currently invisible', 'Identify unmeasured losses, quality variation or unmet needs that alter decisions. Propose a measurement service, explain how customers would act on its output and compare its cost with avoidable losses.', array['technology_agent','evidence_agent','market_agent']),
 (36, 'technology', 'Reveal the capability ladder needed to enter a new value chain', 'Break the target capability into equipment, skills, standards, process knowledge and supplier access. Identify what to build, buy or partner for first and the commercial milestone each step enables.', array['technology_agent','strategy_agent','execution_agent']),
 (37, 'technology', 'Find modular pathways that lower the cost of experimentation', 'Decompose the solution into modules that can be tested independently. Compare rental, shared facilities and incremental capacity, while identifying interface risks and costs that modularity cannot remove.', array['technology_agent','financial_agent','execution_agent']),
 (38, 'technology', 'Expose opportunities at the interface between two technologies', 'Identify capabilities that become useful only when combined. Explain the interaction, the missing integration work and the new customer outcome, then test whether integration value exceeds added complexity.', array['science_agent','technology_agent','systems_agent']),
 (39, 'technology', 'Discover a defensible advantage beyond owning equipment', 'Compare process know-how, reliable supply, qualification data, service networks and trusted execution. Identify which advantages can compound over time and which competitors could reproduce quickly.', array['technology_agent','strategy_agent','market_agent']),
 (40, 'technology', 'Design the experiment most likely to disprove the opportunity', 'Name the most dangerous technical or adoption assumption. Specify a minimum test, comparison baseline, measurement method, budget drivers and stop criteria before proposing further development.', array['risk_agent','technology_agent','execution_agent']),
 (41, 'futures', 'Reveal opportunities across divergent future scenarios', 'Construct four plausible futures using two consequential uncertainties. Identify robust opportunities and scenario-dependent bets, and specify observable signposts rather than assigning unsupported probabilities.', array['foresight_agent','opportunity_agent','strategy_agent']),
 (42, 'futures', 'Uncover weak signals that deserve investigation', 'Look for early changes in behavior, technology, costs or institutional priorities. Explain the mechanism by which each could matter, competing interpretations and evidence needed to distinguish signal from noise.', array['foresight_agent','evidence_agent','risk_agent']),
 (43, 'futures', 'Expose dependencies behind an ambitious transformation', 'Work backward from the desired outcome to the capabilities, institutions, infrastructure and demand required. Identify critical dependencies, circular assumptions and an achievable first commercial step.', array['systems_agent','causal_agent','strategy_agent']),
 (44, 'futures', 'Discover businesses that make the system more resilient', 'Stress-test supply interruption, price shocks, climate events and workforce loss. Identify redundancy, repair, storage or local capability services, and distinguish resilience value from excess capacity with no buyer.', array['foresight_agent','risk_agent','opportunity_agent']),
 (45, 'futures', 'Reveal how an apparently attractive opportunity could become harmful', 'Map who gains, who bears costs and what impacts may be displaced elsewhere. Identify safeguards, consent needs and outcome measures, then redesign the business to reduce harm while retaining useful value.', array['systems_agent','risk_agent','strategy_agent']),
 (46, 'futures', 'Uncover opportunities that survive adverse economics', 'Stress-test price, utilization, input cost, financing and exchange-rate assumptions. Identify break-even drivers and redesign the offer around resilience rather than optimistic forecasts.', array['financial_agent','foresight_agent','risk_agent']),
 (47, 'futures', 'Reveal the real options hidden in a small first investment', 'Compare reversible pilots with irreversible commitments. Show what each stage teaches, which later choices it preserves and the evidence threshold for expanding, partnering, pausing or stopping.', array['financial_agent','strategy_agent','execution_agent']),
 (48, 'futures', 'Find an opportunity portfolio with complementary risks', 'Compare candidates by customer, resource, technology, capital and execution dependencies. Identify correlated failure risks and sequence a portfolio whose early learning or cash flow can support later ventures.', array['opportunity_agent','financial_agent','strategy_agent']),
 (49, 'futures', 'Challenge the accepted boundaries of the opportunity', 'Reframe the subject from the perspectives of a customer, supplier, scientist, community and skeptical investor. Expose conflicting assumptions and identify the deeper problem that a stronger business would solve.', array['reality_agent','systems_agent','risk_agent']),
 (50, 'futures', 'Unveil an integrated opportunity and execution roadmap', 'Connect overlooked resources, causal bottlenecks, scientific mechanisms and unmet demand. Shortlist the strongest opportunities, red-team each one and build a 12-month sequence of validation, pilot and investment gates.', array['reality_agent','systems_agent','opportunity_agent','strategy_agent','execution_agent'])
)
insert into public.prompt_templates(prompt_number, category, template, workflow)
select 50 + (s.n - 1) * 50 + l.n,
 s.category,
 l.instruction || ' for [SUBJECT] in ' || s.category || ' within [LOCATION]. Examine ' ||
 case l.focus when 'resources' then s.resources when 'systems' then s.systems
 when 'markets' then s.markets when 'technology' then s.technology else s.futures end || '. ' ||
 l.deliverable || ' Distinguish evidence from hypotheses, name what remains unknown, and do not invent statistics or sources.',
 l.agents || case when 'evidence_agent' = any(l.agents) then array['integrator_agent'] else array['evidence_agent','integrator_agent'] end
from sectors s cross join lenses l
order by s.n, l.n
on conflict (prompt_number) do nothing;

